import React, { useState, useContext } from 'react';
import Form from '@rjsf/core';
import validator from '@rjsf/validator-ajv8';
import axios from 'axios';
import { Web3Context } from '../contexts/Web3Context';

const schema = {
  title: " ",
  type: "object",
  required: ["topic", "question_content", "correct_option_index"],
  properties: {
    topic: { type: "string", title: "CHỦ ĐỀ", enum: ["Grammar", "Vocabulary", "Reading", "IELTS"] },
    question_content: { type: "string", title: "NỘI DUNG CÂU HỎI", minLength: 10 },
    options: { 
      type: "array", title: "CÁC LỰA CHỌN (4 ĐÁP ÁN)", minItems: 4, maxItems: 4, 
      items: { type: "string", default: "" } 
    },
    correct_option_index: { 
      type: "integer", title: "ĐÁP ÁN ĐÚNG (0-3)", enum: [0, 1, 2, 3],
      enumNames: ["Đáp án 1", "Đáp án 2", "Đáp án 3", "Đáp án 4"] 
    },
    stake_amount: { type: "integer", title: "MỨC CƯỢC (TOKEN)", default: 5 }
  }
};

const uiSchema = {
  question_content: { "ui:widget": "textarea", "ui:options": { rows: 4, placeholder: "Nhập câu hỏi tiếng Anh của bạn..." } },
  stake_amount: { "ui:widget": "updown" }
};

const CreatorStudio = () => {
  const { currentAccount } = useContext(Web3Context);
  
  // State quản lý trạng thái chi tiết
  const [status, setStatus] = useState("idle"); // idle, processing, success, error
  const [logs, setLogs] = useState([]); // Mảng lưu các bước thực hiện

  const addLog = (msg) => setLogs(prev => [...prev, msg]);

  const onSubmit = async ({ formData }) => {
    if (!currentAccount) return alert("Vui lòng kết nối ví!");
    
    setStatus("processing");
    setLogs(["⏳ Đang gửi dữ liệu lên Server..."]);

    try {
      // Giả lập độ trễ để người dùng thấy hiệu ứng AI
      setTimeout(() => addLog("🤖 AI đang đọc và phân tích nội dung..."), 1000);

      const payload = { ...formData, creator_address: currentAccount };
      const res = await axios.post('http://localhost:5000/api/exercises/create', payload);
      
      if (res.data.success) {
        addLog("✅ AI Check: Hợp lệ (Clean Content)");
        addLog(`📦 IPFS Upload: Thành công (Hash: ${res.data.ipfs_hash.slice(0, 10)}...)`);
        addLog("🎉 Hoàn tất: Bài tập đã lên sóng!");
        setStatus("success");
      } else {
        addLog(`❌ AI TỪ CHỐI: ${res.data.message}`);
        setStatus("error");
      }

    } catch (err) {
      addLog(`❌ Lỗi hệ thống: ${err.message}`);
      setStatus("error");
    }
  };

  return (
    <div className="pt-28 pb-10 px-6 min-h-screen flex justify-center">
      <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-8">
        
        {/* Cột trái: Form */}
        <div className="glass-panel p-8 animate-fade-in-up">
          <div className="mb-6">
            <h2 className="text-3xl font-heading font-bold text-white">Creator Studio</h2>
            <p className="text-gray-400">Tạo nội dung kiếm tiền (Create-to-Earn)</p>
          </div>
          
          <Form 
            schema={schema} 
            uiSchema={uiSchema} 
            validator={validator} 
            onSubmit={onSubmit}
            className="rjsf-dark" // Class tùy chỉnh cho dark mode
          >
            <button 
              type="submit" 
              disabled={status === 'processing'}
              className={`w-full mt-6 py-3 rounded-xl font-bold text-white transition-all ${
                status === 'processing' ? 'bg-gray-600 cursor-wait' : 'btn-gradient shadow-lg hover:scale-105'
              }`}
            >
              {status === 'processing' ? 'Đang xử lý...' : '🚀 Gửi Kiểm Duyệt'}
            </button>
          </Form>
        </div>

        {/* Cột phải: Trạng thái AI (Console Log Real-time) */}
        <div className="flex flex-col gap-6 animate-fade-in-up" style={{ animationDelay: '0.2s' }}>
          
          {/* AI Monitor Card */}
          <div className="glass-panel p-6 border-l-4 border-indigo-500 h-full relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-20">
              <span className="text-6xl">🤖</span>
            </div>
            <h3 className="text-xl font-bold text-white mb-4">AI Moderation Log</h3>
            
            <div className="bg-black/40 rounded-lg p-4 h-64 overflow-y-auto font-mono text-sm border border-white/5 shadow-inner">
              {logs.length === 0 ? (
                <p className="text-gray-500 italic">...Chờ dữ liệu nhập...</p>
              ) : (
                logs.map((log, idx) => (
                  <div key={idx} className={`mb-2 ${
                    log.includes('❌') ? 'text-red-400' : 
                    log.includes('✅') ? 'text-emerald-400' : 
                    log.includes('🎉') ? 'text-yellow-300 font-bold' : 'text-blue-300'
                  }`}>
                    <span className="opacity-50 mr-2">[{new Date().toLocaleTimeString()}]</span>
                    {log}
                  </div>
                ))
              )}
              {status === 'processing' && (
                <div className="animate-pulse text-indigo-400 mt-2">_ AI is typing...</div>
              )}
            </div>

            {/* Status Summary */}
            <div className="mt-6">
              {status === 'success' && (
                <div className="p-4 bg-emerald-500/20 border border-emerald-500/30 rounded-xl text-emerald-300 flex items-center gap-3">
                  <span className="text-2xl">✅</span>
                  <div>
                    <p className="font-bold">Đã duyệt thành công!</p>
                    <p className="text-xs opacity-80">Bài tập đã được lưu vĩnh viễn trên IPFS.</p>
                  </div>
                </div>
              )}
              {status === 'error' && (
                <div className="p-4 bg-red-500/20 border border-red-500/30 rounded-xl text-red-300 flex items-center gap-3">
                  <span className="text-2xl">⛔</span>
                  <div>
                    <p className="font-bold">Bài đăng bị từ chối</p>
                    <p className="text-xs opacity-80">Vui lòng kiểm tra lại nội dung.</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default CreatorStudio;
